package com.berkeh.connector;
import android.content.*;import android.provider.Telephony;import android.telephony.SmsMessage;import org.json.*;import java.text.SimpleDateFormat;import java.util.*;
public final class SmsReceiver extends BroadcastReceiver {
 public void onReceive(Context c,Intent i){if(!Telephony.Sms.Intents.SMS_RECEIVED_ACTION.equals(i.getAction())||!Config.enabled(c))return;SmsMessage[] parts=Telephony.Sms.Intents.getMessagesFromIntent(i);if(parts==null||parts.length==0)return;String sender=parts[0].getOriginatingAddress();if(!Config.allowed(sender,Config.get(c,"senders")))return;StringBuilder b=new StringBuilder();for(SmsMessage p:parts)b.append(p.getMessageBody());String body=b.toString();if(Config.otp(body))return;long time=parts[0].getTimestampMillis();PendingResult pending=goAsync();new Thread(()->{try(Store s=new Store(c)){if(!Config.enabled(c))return;SimpleDateFormat f=new SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss'Z'",Locale.US);f.setTimeZone(TimeZone.getTimeZone("UTC"));String id="android-"+Crypto.hash(sender+"|"+time+"|"+body);JSONObject data=Api.identity(c).put("message_id",id).put("body",body).put("sender",sender).put("received_at",f.format(new Date(time))).put("source","android-app");s.add(id,data.toString(),sender,time);SyncJob.schedule(c);}catch(Exception e){Config.prefs(c).edit().putString("last","ذخیره پیامک ناموفق بود؛ فضای گوشی را بررسی کنید.").apply();}finally{pending.finish();}},"berkeh-sms").start();}
}
